def fix_spaces(text):
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == ' ':
            start = i
            while i < n and text[i] == ' ':
                i += 1
            count = i - start
            if count > 2:
                result.append('-')
            else:
                result.append('_' * count)
        else:
            result.append(text[i])
            i += 1

    return ''.join(result)
