    result = []
    count = 0
    for char in text:
        if char == ' ':
            count += 1
        else:
            if count == 1:
                result.append('_')
            elif count > 1:
                result.append('-')
            count = 0
            result.append(char)
    if count == 1:
        result.append('_')
    elif count > 1:
